// Each brief describes the visible result. Reference source is only exposed by
// the workshop's deliberate reveal action, never placed in starter editors.
export const designLevels = [
  { id: "level-1", level: 1, title: "Build the basics", description: "Tables, lists, cards, and thoughtful styling.", js: false },
  { id: "level-2", level: 2, title: "Compose a page", description: "Responsive layouts, forms, and complete sections.", js: false },
  { id: "level-3", level: 3, title: "Make it interactive", description: "Bring small interfaces to life with JavaScript.", js: true },
  { id: "level-4", level: 4, title: "Build useful interfaces", description: "Combine HTML, CSS, and JavaScript in working tools.", js: true },
];

const palettes = [
  ["#4f46e5", "#eef2ff", "Indigo"], ["#0f766e", "#f0fdfa", "Teal"],
  ["#9d174d", "#fff1f2", "Rose"], ["#0369a1", "#f0f9ff", "Sky"],
  ["#6d28d9", "#f5f3ff", "Violet"], ["#92400e", "#fffbeb", "Amber"],
  ["#166534", "#f0fdf4", "Forest"], ["#9a3412", "#fff7ed", "Copper"],
];
const people = ["Maya Chen", "Arun Patel", "Nora Kim", "Leo Martin", "Asha Rao", "Sam Rivera", "Iris Park", "Omar Ali"];
const places = ["Kyoto", "Porto", "Jaipur", "Oslo", "Seoul", "Lima", "Bristol", "Utrecht"];
const topics = ["Design systems", "Accessible forms", "CSS layouts", "Typography", "Responsive grids", "Web animation", "Semantic HTML", "Color theory"];
const products = ["Canvas tote", "Studio notebook", "Ceramic mug", "Desk planter", "Travel flask", "Art print", "Reading lamp", "Wool cushion"];
const escape = value => String(value).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const jsValue = value => JSON.stringify(value).replace(/</g, "\\u003c");
const text = (selector, equals, message = `Show “${equals}” in ${selector}.`, essential = true) => ({ type: "text", selector, equals: String(equals), message, weight: 2, essential });
const exists = (selector, count = 1, message = `Include ${count} matching ${selector} element${count === 1 ? "" : "s"}.`) => ({ type: "exists", selector, count, message, weight: 2, essential: true });
const style = (selector, property, value, message = `Set ${selector} ${property} to ${value}.`) => ({ type: "style", selector, property, value, message, weight: 1, essential: /^(display|flex-direction|grid-template-columns|grid-column|justify-content|overflow-x|flex-wrap)$/.test(property) });
const attribute = (selector, name, value, message = `Set ${selector} ${name} to ${value}.`) => ({ type: "attribute", selector, name, value: String(value), message, weight: 2, essential: true });
const action = (type, selector, value) => ({ type, selector, ...(value === undefined ? {} : { value: String(value) }) });
const behavior = (actions, expect, message) => ({ type: "behavior", actions, expect, reset: true, message, weight: 4, essential: true });
const click = selector => action("click", selector);
const input = (selector, value) => action("input", selector, value);
const change = (selector, value) => action("change", selector, value);

function context(n) {
  const i = n % 8;
  const [accent, tint, color] = palettes[i];
  return { n, accent, tint, color, person: people[i], other: people[(i + 3) % 8], city: places[i], topic: topics[i], nextTopic: topics[(i + 2) % 8], item: products[i], otherItem: products[(i + 1) % 8], thirdItem: products[(i + 2) % 8], price: 18 + n % 23, number: 3 + n % 7, day: 10 + n % 18, reference: 1000 + n % 997 };
}

function baseCss(c) {
  return `:root{--accent:${c.accent};--tint:${c.tint};--ink:#172033;--muted:#64748b;--line:#e2e8f0}*{box-sizing:border-box}body{margin:0;padding:28px;background:#f1f5f9;color:var(--ink);font:15px/1.5 Arial,sans-serif}#challenge{max-width:720px;margin:auto;background:white;border:1px solid var(--line);border-radius:20px;padding:28px;box-shadow:0 8px 28px #0f172a08}h1,h2,h3,p{margin:0 0 12px}h1{font-size:26px;line-height:1.2;letter-spacing:-.7px}h2{font-size:19px}h3{font-size:16px}p,.muted{color:var(--muted)}.eyebrow{color:var(--accent);text-transform:uppercase;letter-spacing:2px;font-size:11px;font-weight:700;margin-bottom:8px}.lead{margin-bottom:24px}.panel{border:1px solid var(--line);border-radius:14px;padding:20px}.row{display:flex;align-items:center;justify-content:space-between;gap:16px}.stack{display:grid;gap:16px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.tag{display:inline-block;border-radius:20px;background:var(--tint);color:var(--accent);padding:4px 12px;font-size:12px;font-weight:bold}button,.button{display:inline-block;border:0;border-radius:10px;background:var(--accent);color:white;padding:11px 18px;font:700 14px Arial,sans-serif;cursor:pointer;text-decoration:none}button.secondary{background:var(--tint);color:var(--accent)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--accent);outline-offset:3px}input,select,textarea{width:100%;border:1px solid #cbd5e1;border-radius:9px;padding:11px;font:inherit;background:white;color:var(--ink)}label{display:block;font-weight:600;margin-bottom:6px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{background:var(--tint);color:var(--accent);font-size:13px}caption{text-align:left;font-size:18px;font-weight:bold;margin-bottom:14px}ul,ol{margin:0;padding-left:22px}li{padding:7px 0}a{color:var(--accent)}output{font-weight:700}hr{border:0;border-top:1px solid var(--line);margin:18px 0}[hidden]{display:none!important}.large-number{font-size:40px;font-weight:800;line-height:1.2;color:var(--accent)}.swatch{height:110px;display:grid;place-items:center;background:var(--tint);border-radius:10px;color:var(--accent);font-size:30px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}@media(max-width:520px){body{padding:12px}#challenge{padding:20px}.grid,.form-grid{grid-template-columns:1fr}.row{flex-wrap:wrap}h1{font-size:23px}}`;
}

function build(c, title, subtitle, html, css = "", js = "", requirements = [], checks = []) {
  const brief = `${c.color} studio · Brief #${c.reference}`;
  const solution = { html: `<main id="challenge"><p class="eyebrow" id="brief">${escape(brief)}</p><h1 id="title">${escape(title)}</h1><p class="lead">${escape(subtitle)}</p>${html}</main>`, css: baseCss(c) + css, js };
  const baseline = [
    style("body", "background-color", "#f1f5f9", "Use the soft #f1f5f9 canvas behind the reference panel."),
    style("body", "font-family", "Arial, sans-serif", "Use Arial with a sans-serif fallback."),
    style("body", "color", "#172033", "Use #172033 for the page’s primary text."),
    style("#challenge", "background-color", "#ffffff", "Give the main panel a white surface."),
    style("#challenge", "border-radius", "20px", "Use 20px rounded corners on the main panel."),
    style("#challenge", "border-width", "1px", "Add a 1px border around the main panel."),
    style("#challenge", "border-color", "#e2e8f0", "Use #e2e8f0 for the main panel border."),
    { ...style("#challenge", "padding", "28px", "Use 28px main-panel padding, reducing to 20px at widths up to 520px."), responsive: [{ maxWidth: 520, value: "20px" }] },
    { ...style("#title", "font-size", "26px", "Use a 26px heading, reducing to 23px at widths up to 520px."), responsive: [{ maxWidth: 520, value: "23px" }] },
    style("#title", "font-weight", "700", "Keep the main heading bold."),
  ];
  const allChecks = [text("#title", title), text("#brief", brief), ...checks, ...baseline];
  // Appearance has a meaningful share of the score even for data-rich tables.
  // Correct text alone should never count as a finished visual recreation.
  const visualChecks = allChecks.filter(check => check.type === "style");
  const functionalWeight = allChecks.filter(check => check.type !== "style").reduce((sum, check) => sum + check.weight, 0);
  const visualWeight = Number((functionalWeight * 0.75 / visualChecks.length).toFixed(3));
  visualChecks.forEach(check => { check.weight = visualWeight; });
  // Explicit selector contracts let the checker accept any implementation with
  // the right result rather than comparing a learner's source with ours.
  const selectors = [...new Set(allChecks.flatMap(check => check.type === "behavior" ? [...check.actions.map(a => a.selector), ...(Array.isArray(check.expect) ? check.expect : [check.expect]).map(e => e.selector)] : [check.selector]).filter(s => s && s !== "#title"))];
  return { solution, requirements: [...requirements, `Studio brief label: ${brief}. Use #brief for this label and #title for the main heading. Keep these checking selectors: ${selectors.join(", ")}.`, `Use ${c.accent} as the accent and ${c.tint} for pale accent surfaces. Canvas: #f1f5f9; primary text: #172033; font: Arial, sans-serif. The white #challenge panel has a 1px #e2e8f0 border, 20px corners, and 28px padding. The bold heading is 26px. At widths up to 520px use 20px panel padding and a 23px heading.`], checks: allChecks };
}

const templates = [];
const define = (id, level, title, description, render) => templates.push({ id, level, title, description, render });

// LEVEL 1: fifteen different semantic and styling problems.
define("l1-table", 1, "Workshop schedule", "Build a readable table from exact supplied data.", c => {
  const rows = [[c.topic, c.person, "09:00", `${c.number} seats`], [c.nextTopic, c.other, "11:00", `${c.number + 4} seats`], ["Open studio", "Design team", "14:00", "Drop in"]];
  return build(c, `${c.city} workshop schedule`, "A small learning day, clearly organized.", `<div id="schedule-scroll"><table id="schedule"><caption>${c.city} learning day</caption><thead><tr>${["Session", "Mentor", "Time", "Availability"].map(s => `<th scope="col">${s}</th>`).join("")}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(v => `<td>${escape(v)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`, "#schedule-scroll{overflow-x:auto}#schedule{border:1px solid var(--line)}#schedule th{font-weight:700}", "", [`Caption: “${c.city} learning day”. Columns in order: Session, Mentor, Time, Availability.`, ...rows.map((row, i) => `Row ${i + 1}: ${row.join(" | ")}.`), "Use real table header/data cells, collapsed borders, left-aligned cells, and 12px cell padding. Place the table in #schedule-scroll with overflow-x:auto for narrow screens."], [exists("#schedule thead th", 4), exists("#schedule tbody tr", 3), text("#schedule caption", `${c.city} learning day`), ...rows.flatMap((row, i) => row.map((v, j) => text(`#schedule tbody tr:nth-child(${i + 1}) td:nth-child(${j + 1})`, v))), style("#schedule", "border-collapse", "collapse"), style("#schedule th", "text-align", "left"), style("#schedule td", "padding", "12px"), style("#schedule-scroll", "overflow-x", "auto")]);
});
