define("l1-profile", 1, "Mentor card", "Create a profile card with a circular initials avatar.", c => build(c, "Meet your mentor", `Good questions start good conversations.`, `<article id="mentor" class="panel"><div id="avatar">${c.person.split(" ").map(n => n[0]).join("")}</div><h2 id="name">${c.person}</h2><p id="role">${c.topic} mentor</p><span id="location" class="tag">${c.city}</span></article>`, "#mentor{text-align:center}#avatar{width:72px;height:72px;border-radius:50%;margin:0 auto 16px;background:var(--tint);color:var(--accent);display:grid;place-items:center;font-size:24px;font-weight:bold}", "", [`Name: ${c.person}. Role: ${c.topic} mentor. Location: ${c.city}.`, "Show the mentor’s initials in a 72px circular avatar. Center the card contents."], [text("#name", c.person), text("#role", `${c.topic} mentor`), text("#location", c.city), text("#avatar", c.person.split(" ").map(n => n[0]).join("")), style("#avatar", "border-radius", "50%"), style("#avatar", "width", "72px"), style("#mentor", "text-align", "center")]));
